{
  "subtype": "faceted_decomposition",
  "concept": "goal_management_success_factors",
  "per_column": [
    {
      "name": "primary_intervention_type",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The type of intervention/lever used is a constitutive aspect of how a goal is managed -- a 'what practice' facet of goal-management practice."
    },
    {
      "name": "timeframe_specificity",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "How specifically the goal is bounded in time is a genuine aspect of goal-management discipline (time-bounding), a facet of the practice itself."
    },
    {
      "name": "baseline_referenced",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Whether a baseline is referenced is an aspect of the goal-setting/measurement discipline -- a part of good goal management practice."
    },
    {
      "name": "measurement_mechanism",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The mechanism by which progress is measured is a constitutive facet of goal management (the measurement dimension of a practice)."
    },
    {
      "name": "metric_category_alignment",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Alignment between metric and category is an aspect of goal-definition coherence, a facet of the practice, though it overlaps with the measurement dimension."
    },
    {
      "name": "scope_of_change",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The organizational scope targeted is a legitimate aspect of how a goal/practice is framed -- a scoping facet."
    },
    {
      "name": "multi_lever_approach",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "Whether multiple levers are used is largely a derivative/restatement of primary_intervention_type (breadth of intervention), overlapping with the intervention-type facet rather than adding an orthogonal aspect."
    },
    {
      "name": "technology_enablement",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "Technology enablement substantially overlaps with intervention_type values like 'automation'/'system_kpi'; it re-expresses part of the intervention facet rather than carving a distinct aspect."
    }
  ],
  "facet_columns": [
    "primary_intervention_type",
    "timeframe_specificity",
    "baseline_referenced",
    "measurement_mechanism",
    "metric_category_alignment",
    "scope_of_change"
  ],
  "non_facet_columns": [
    "multi_lever_approach",
    "technology_enablement"
  ],
  "mutual_exclusivity": 0.55,
  "exhaustiveness": 0.6,
  "rationale": "Most columns are genuine part-of facets of goal-management practice, spanning intervention type, time-bounding, measurement discipline, and scope. However mutual exclusivity is weakened by clustering: baseline_referenced, measurement_mechanism, and metric_category_alignment all address the measurement/definition aspect, while multi_lever_approach and technology_enablement overlap with primary_intervention_type. Exhaustiveness is moderate: the set covers the 'what/when/how-measured/where' dimensions but omits key goal-management facets such as ownership/accountability, prioritization, progress-monitoring cadence, and stakeholder engagement, so it does not fully cover the concept's constitutive aspects."
}
